public static List<JSONObject> createAlarmConfigPidList1(AlarmConfigInfo alarmConfigInfo) {
    LogUtils.d("<literal omitted>", "<literal omitted>" + alarmConfigInfo + "<literal omitted>");
    if (alarmConfigInfo == null) {
        return null;
    }
    ArrayList arrayList = new ArrayList();
    arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MAIN_SW, alarmConfigInfo.isbMainAlarmSwitch()));
    arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_MT_SW, alarmConfigInfo.isbMotionAlarmSwitch()));
    arrayList.add(createBooleanValueJsonObj(Protocol.DPID_ALARM_SOUND_SW, alarmConfigInfo.isbAlarmVoiceSwitch()));
    AlarmTimeSetJsonParse alarmTimeSetJsonParse = alarmConfigInfo.getAlarmTimeSetJsonParse();
    JSONObject jSONObject = new JSONObject();
    try {
        jSONObject = new JSONObject(new Gson().toJson(alarmTimeSetJsonParse));
    } catch (JSONException e) {
        e.printStackTrace();
    }
    arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_TIMER_INFO, jSONObject));
    AlarmAreaJsonParse alarmAreaJsonParse = new AlarmAreaJsonParse();
    alarmAreaJsonParse.setAlarmAreaRowCnt(alarmConfigInfo.getAlarmrows());
    alarmAreaJsonParse.setAlarmAreaLineCnt(alarmConfigInfo.getAlarmcolumns());
    alarmAreaJsonParse.setAlarmArea(alarmConfigInfo.getAlarmAreaList());
    JSONObject jSONObject2 = new JSONObject();
    try {
        jSONObject2 = new JSONObject(new Gson().toJson(alarmAreaJsonParse));
    } catch (JSONException e2) {
        e2.printStackTrace();
    }
    arrayList.add(createJSONObjectValueJsonObj(Protocol.DPID_ALARM_MT_AREA, jSONObject2));
    LogUtils.d("<literal omitted>", "<literal omitted>" + arrayList);
    return arrayList;
}
